using System;using System.IO;using System.Linq;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.XR.Interaction.Toolkit.Locomotion.Teleportation;using Unity.XR.CoreUtils;using ProyectoVR.UI;using UnityEngine.XR.Interaction.Toolkit.Inputs.Simulation;using UnityEngine.XR.Interaction.Toolkit.Locomotion.Movement;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;
[InitializeOnLoad]public static class StairSimulatorCheck{
const string Flag="Vivienda.StairSim";static StringBuilder report=new();static Vector3 walkingStart;static XROrigin rig;static Keyboard keyboard;static TeleportationProvider provider;static Key[] held=Array.Empty<Key>();static int phase,errors,failed;static float next,deadline,sample;static StairSimulatorCheck(){EditorApplication.playModeStateChanged+=State;}
[MenuItem("Vivienda/XR/Probar escaleras con joystick simulado")]public static void Begin(){NativeXrProjectSettings.Simulator();SessionState.SetBool(Flag,true);EditorApplication.EnterPlaymode();}
static void State(PlayModeStateChange s){if(!SessionState.GetBool(Flag,false))return;if(s==PlayModeStateChange.EnteredPlayMode){report.Clear();phase=failed=errors=0;next=Time.realtimeSinceStartup+3;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;}if(s==PlayModeStateChange.ExitingPlayMode){EditorApplication.update-=Tick;Application.logMessageReceived-=Log;InputSystem.onBeforeUpdate-=Feed;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);}if(s==PlayModeStateChange.EnteredEditMode)SessionState.SetBool(Flag,false);}
static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert){errors++;report.AppendLine("ERROR "+m);}}
static void Press(params Key[] keys){held=keys;var sim=XRInteractionSimulator.instance;if(sim!=null)sim.axis2DInput.manualValue=new Vector2(keys.Contains(Key.L)?1:keys.Contains(Key.J)?-1:0,keys.Contains(Key.I)?1:keys.Contains(Key.K)?-1:0);}static void Feed(){if(keyboard!=null&&keyboard.added)InputSystem.QueueStateEvent(keyboard,new KeyboardState(held));}
static void Queue(Vector3 pos){provider.QueueTeleportRequest(new TeleportRequest{destinationPosition=pos,destinationRotation=Quaternion.Euler(0,180,0),matchOrientation=MatchOrientation.TargetUpAndForward,requestTime=Time.time});}
static void Save(){Directory.CreateDirectory("Validation");File.WriteAllText("Validation/StairSimulator-Progress.txt",report.ToString());}
static void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)failed++;Save();}
static void Finish(){Press();Check(errors==0,"Errores Play="+errors);report.AppendLine("Fallos="+failed);File.WriteAllLines("Validation/StairSimulator.txt",new[]{"Escaleras: XR Interaction Simulator, eje izquierdo mediante lector nativo; WASD mediante teclado simulado."}.Concat(report.ToString().Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries).Where(line=>line.StartsWith("PASS ")||line.StartsWith("FAIL ")||line.StartsWith("Fallos="))));EditorApplication.ExitPlaymode();}
static void Tick(){if(!EditorApplication.isPlaying||Time.realtimeSinceStartup<next)return;try{
if(phase==0){rig=UnityEngine.Object.FindAnyObjectByType<XROrigin>();provider=rig.GetComponentInChildren<TeleportationProvider>();keyboard=InputSystem.AddDevice<Keyboard>("Stair simulator test");held=Array.Empty<Key>();InputSystem.onBeforeUpdate+=Feed;VrWorldMenuController.Instance.SetVisible(false);foreach(var door in UnityEngine.Object.FindObjectsByType<ProyectoVR.DoorHinge>())if(door.enabled)door.Toggle();XRInteractionSimulator.instance.axis2DInput.inputSourceMode=XRInputValueReader.InputSourceMode.ManualValue;XRInteractionSimulator.instance.leftDeviceActionsInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;XRInteractionSimulator.instance.leftDeviceActionsInput.manualPerformed=true;XRInteractionSimulator.instance.leftDeviceActionsInput.manualValue=1;Press(Key.LeftBracket);phase=1;next=Time.realtimeSinceStartup+.7f;return;}
if(phase==1){Press();Queue(new Vector3(4.11f,.04f,9.15f));phase=2;next=Time.realtimeSinceStartup+.7f;return;}
if(phase==2){Press(Key.I);deadline=Time.realtimeSinceStartup+13;sample=0;phase=3;}
if(Time.realtimeSinceStartup>sample){sample=Time.realtimeSinceStartup+.5f;var c=rig.Origin.GetComponent<CharacterController>();report.AppendLine("TRACE phase="+phase+" feet="+rig.transform.position.ToString("F3")+" cameraLocal="+rig.Camera.transform.localPosition.ToString("F3")+" grounded="+c.isGrounded+" center="+c.center.ToString("F3"));var sim=XRInteractionSimulator.instance;var mv=rig.GetComponentsInChildren<ContinuousMoveProvider>().First(m=>m.GetType()==typeof(ContinuousMoveProvider));report.AppendLine("INPUT left="+sim.currentState.manipulatingLeftController+" fps="+sim.currentState.manipulatingFPS+" rawAxis="+sim.axis2DInput.ReadValue()+" nativeMove="+mv.leftHandMoveInput.ReadValue()+" keyboardI="+keyboard.iKey.isPressed+" moveEnabled="+mv.leftHandMoveInput.inputActionReference.action.enabled+" controls="+string.Join(",",mv.leftHandMoveInput.inputActionReference.action.controls.Select(x=>x.path)));Save();}
if(phase==3){if(rig.transform.position.z<3.7f&&rig.transform.position.y>2.8f){Press();Check(true,"Subida completa por joystick del simulador "+rig.transform.position);phase=4;next=Time.realtimeSinceStartup+.3f;return;}if(Time.realtimeSinceStartup>deadline){Check(false,"Subida bloqueada "+rig.transform.position);var c=rig.Origin.GetComponent<CharacterController>();foreach(var hit in Physics.OverlapCapsule(rig.transform.TransformPoint(c.center)+Vector3.up*(c.height*.5f-c.radius),rig.transform.TransformPoint(c.center)-Vector3.up*(c.height*.5f-c.radius),c.radius+.03f,~0,QueryTriggerInteraction.Ignore))report.AppendLine("NEAR "+hit.name+" "+hit.bounds);Finish();}return;}
if(phase==4){Press(Key.L);deadline=Time.realtimeSinceStartup+2;phase=5;return;}
if(phase==5){if(rig.transform.position.x<3.45f||Time.realtimeSinceStartup>deadline){Press();Check(rig.transform.position.x<3.45f&&rig.transform.position.y>2.8f,"Salida al descanso superior "+rig.transform.position);Queue(new Vector3(4.11f,3.04f,3.65f));phase=6;next=Time.realtimeSinceStartup+.7f;}return;}
if(phase==6){Press(Key.K);deadline=Time.realtimeSinceStartup+13;phase=7;return;}
if(phase==7){if(rig.transform.position.z>8.9f&&rig.transform.position.y<.3f){Check(true,"Bajada completa por joystick del simulador "+rig.transform.position);Press();Queue(new Vector3(.2f,.04f,9.8f));phase=8;next=Time.realtimeSinceStartup+.7f;return;}if(Time.realtimeSinceStartup>deadline){Check(false,"Bajada bloqueada "+rig.transform.position);Finish();}}
if(phase==8){walkingStart=rig.transform.position;Press(Key.W);deadline=Time.realtimeSinceStartup+1;phase=9;return;}
if(phase==9&&Time.realtimeSinceStartup>deadline){Press();Check(Vector3.ProjectOnPlane(rig.transform.position-walkingStart,Vector3.up).magnitude>.8f,"WASD mueve el cuerpo por locomocion nativa");Check(Vector3.ProjectOnPlane(rig.Camera.transform.localPosition,Vector3.up).magnitude<.01f,"WASD no desplaza el visor dentro de la capsula");Finish();}
}catch(Exception e){Check(false,e.ToString());Finish();}}
}
